import {svg,palette,text,legend,esc} from '../gallery-utils.js';
export function render({data,params:p}){const total=+p.total;for(const d of data)if(Math.min(d.a,d.b,d.c)<0||Math.abs(d.a+d.b+d.c-total)>total*1e-6)throw Error('三组分必须非负且总和为 '+total+'；不会自动归一');const side=Math.min(p.width-260,(p.height-160)/.866),x0=100,y0=p.height-80,h=side*Math.sqrt(3)/2;const xy=(a,b,c)=>[x0+side*(c/total+a/total/2),y0-h*a/total];let s='';for(let i=0;i<=5;i++){const v=total*i/5;for(const pair of [[[v,total-v,0],[v,0,total-v]],[[0,v,total-v],[total-v,v,0]],[[total-v,0,v],[0,total-v,v]]]){const [a,b]=pair.map(v=>xy(...v));s+=`<path d="M${a[0]},${a[1]}L${b[0]},${b[1]}" stroke="${i===0?'#40556a':'#dce5ee'}" fill="none"/>`;}const point=xy(v,total-v,0);s+=text(point[0]-10,point[1],Math.round(v*100/total)+'%','text-anchor="end"');}s+=text(x0+side/2,y0-h-18,p.aLabel,'text-anchor="middle"')+text(x0,y0+28,p.bLabel,'text-anchor="middle"')+text(x0+side,y0+28,p.cLabel,'text-anchor="middle"');const groups=[...new Set(data.map(d=>d.group))],colors=palette(p);for(const d of data){const [x,y]=xy(d.a,d.b,d.c);s+=`<circle cx="${x}" cy="${y}" r="${p.markerSize}" fill="${colors[groups.indexOf(d.group)%colors.length]}" stroke="white"/>`;}return svg(p,s+legend({r:x0+side+10,t:75},groups,colors));}